def _habilitar_timescale() -> None:
    """Hypertable para el historial de estados; fallback a tabla normal sin la extensión."""
    bind = op.get_bind()
    if bind.dialect.name != "postgresql":
        return
    try:
        with bind.begin_nested():
            bind.execute(sa.text("CREATE EXTENSION IF NOT EXISTS timescaledb"))
            bind.execute(
                sa.text("SELECT create_hypertable('estado_barrera_hist', 'ts', migrate_data => true)")
            )
        print("TimescaleDB: estado_barrera_hist creada como hypertable")
    except Exception as exc:  # noqa: BLE001
        print(f"TimescaleDB no disponible ({type(exc).__name__}); se usa tabla normal")


